import { createHash } from 'node:crypto';

/**
 * Build-time only (vite.main.config.ts). The skill manifests generated by
 * scripts/bundle-skills.mjs are TS modules holding every asset as a string
 * literal; impeccable alone carries a 17 MB base64 Mach-O. Inside the Main
 * bundle V8 keeps that source (twice as wide once any non-Latin-1 character
 * shares the chunk) plus a copy of the literal for the whole process, and the
 * parse at boot spikes RSS by hundreds of MB.
 *
 * This rewrites such a module, inside the bundle only, into an index of
 * build-time digests plus a JSON payload emitted next to the chunks (inside
 * the signed app.asar). Small assets such as SKILL.md stay inline; the rest is
 * read from disk only when a file actually has to be written. Tests and every
 * other consumer keep importing the generated module unchanged.
 */

const GENERATED_HEADER = '// Auto-generated by scripts/bundle-skills.mjs.';
const DECLARATION = /export const ([A-Z][A-Z0-9_]*): Record<string, SkillAsset> = /u;

interface GeneratedAsset {
  content: string;
  encoding: 'utf8' | 'base64';
  executable?: boolean;
}

export interface SkillManifestOffloadOptions {
  /** Payload path, relative to the directory of the Main chunks. */
  readonly assetFileName: string;
  /** Assets whose encoded content is at least this long leave the bundle. */
  readonly minContentLength: number;
  /** Specifier of offloaded-skill-manifest as seen from the manifest module. */
  readonly runtimeImport: string;
}

export interface OffloadedSkillManifestModule {
  /** Replacement module code for the Main bundle. */
  readonly code: string;
  /** JSON payload with the content of the offloaded assets. */
  readonly asset: string;
}

function sha256Hex(bytes: Buffer): string {
  return createHash('sha256').update(bytes).digest('hex');
}

/** null when the module is not a generated manifest or has nothing large. */
export function offloadSkillManifest(
  source: string,
  options: SkillManifestOffloadOptions,
): OffloadedSkillManifestModule | null {
  if (!source.startsWith(GENERATED_HEADER)) return null;
  const declaration = DECLARATION.exec(source);
  if (!declaration) return null;
  const jsonStart = declaration.index + declaration[0].length;
  const jsonEnd = source.lastIndexOf(';');
  if (jsonEnd <= jsonStart) return null;
  const manifest = JSON.parse(source.slice(jsonStart, jsonEnd)) as Record<
    string,
    GeneratedAsset
  >;

  const inline: Record<string, object> = {};
  const offloaded: Record<string, object> = {};
  const payload: Record<string, string> = {};
  for (const [relPath, asset] of Object.entries(manifest)) {
    const bytes = Buffer.from(asset.content, asset.encoding);
    const meta = {
      encoding: asset.encoding,
      ...(asset.executable ? { executable: true } : {}),
      sha256: sha256Hex(bytes),
      size: bytes.length,
    };
    if (asset.content.length >= options.minContentLength) {
      offloaded[relPath] = meta;
      payload[relPath] = asset.content;
    } else {
      inline[relPath] = { ...meta, content: asset.content };
    }
  }
  if (Object.keys(offloaded).length === 0) return null;

  const code = [
    `import path from 'node:path';`,
    `import { offloadedSkillManifest } from ${JSON.stringify(options.runtimeImport)};`,
    `export const ${declaration[1]} = offloadedSkillManifest(`,
    `  path.join(__dirname, ${JSON.stringify(options.assetFileName)}),`,
    `  ${JSON.stringify(inline)},`,
    `  ${JSON.stringify(offloaded)},`,
    `);`,
    '',
  ].join('\n');
  return { code, asset: JSON.stringify(payload) };
}
